const input = $input.first() ? $input.first().json : {};
const usuario_id = input.usuario_id || null;
const identidade = input.identidade || null;
const tipo = input.tipo || 'texto_livre';
const variaveis = input.variaveis || {};
const botoes = Array.isArray(input.botoes) ? input.botoes : [];
const SUPA = 'https://zvqwjtndvbqryonjplal.supabase.co/rest/v1';
const select = 'select=id,nome,telefone,canal,telegram_chat_id';
let urlUsuario;
if (usuario_id) {
  urlUsuario = SUPA + '/usuarios?id=eq.' + encodeURIComponent(usuario_id) + '&' + select;
} else if (identidade) {
  const idx = identidade.indexOf(':');
  const prefixo = idx >= 0 ? identidade.slice(0, idx) : '';
  const resto = idx >= 0 ? identidade.slice(idx + 1) : identidade;
  if (prefixo === 'tg') urlUsuario = SUPA + '/usuarios?telegram_chat_id=eq.' + encodeURIComponent(resto) + '&' + select;
  else urlUsuario = SUPA + '/usuarios?telefone=eq.' + encodeURIComponent(resto) + '&' + select;
} else {
  urlUsuario = SUPA + '/usuarios?id=eq.00000000-0000-0000-0000-000000000000&' + select;
}
return [{ json: { usuario_id, identidade, tipo, variaveis, botoes, urlUsuario, urlConfigWpp: SUPA + '/config?chave=eq.whatsapp_habilitado&select=valor' } }];

const ctx = $('Preparar Contexto').first().json;
const users = $input.all().map(i => i.json).filter(u => u && u.id);
const tipo = ctx.tipo;
const v = ctx.variaveis || {};
const botoes = ctx.botoes || [];
function e(s){ return (s === null || s === undefined) ? '' : String(s); }
if (users.length === 0) {
  return [{ json: { ok:false, erro:'usuario_nao_encontrado', canal:'nenhum', tipo } }];
}
const u = users[0];
let text = '';
let wtpl = '';
let wparams = [];
if (tipo === 'rota_diaria') {
  text = 'Bom dia, ' + e(v.nome || u.nome) + '! Sua rota de ' + e(v.data) + ' tem ' + e(v.qtd_visitas) + ' visita(s):\n' + e(v.lista_visitas) + '\nRetornos agendados para hoje: ' + e(v.lista_retornos);
  wtpl = 'rota_diaria'; wparams = [e(v.nome || u.nome), e(v.data), e(v.qtd_visitas), e(v.lista_visitas), e(v.lista_retornos)];
} else if (tipo === 'lembrete_retorno') {
  text = 'Olá, ' + e(v.nome || u.nome) + '! Você tem um retorno agendado hoje na loja ' + e(v.loja) + ' (' + e(v.bairro) + '). Contato: ' + e(v.contato) + '.';
  wtpl = 'lembrete_retorno'; wparams = [e(v.nome || u.nome), e(v.loja), e(v.bairro), e(v.contato)];
} else if (tipo === 'relatorio_diario') {
  text = 'Relatório Rota Viva — ' + e(v.data) + '\nVisitas: ' + e(v.realizadas) + '/' + e(v.planejadas) + ' planejadas (' + e(v.pct_meta) + '% da meta)\nAcumulado mês: ' + e(v.acumulado_mes) + '/280\nCheck-ins suspeitos: ' + e(v.checkins_suspeitos) + '\nOportunidades novas: ' + e(v.oportunidades_novas) + '\nContratos parados além do SLA: ' + e(v.contratos_sla);
  wtpl = 'relatorio_diario_gerente'; wparams = [e(v.data), e(v.realizadas), e(v.planejadas), e(v.pct_meta), e(v.acumulado_mes), e(v.checkins_suspeitos), e(v.oportunidades_novas), e(v.contratos_sla)];
} else if (tipo === 'alerta_rota_vazia') {
  text = 'Atenção, ' + e(v.coordenador || u.nome) + ': a rota de ' + e(v.data) + ' está vazia para ' + e(v.usuario_sem_rota) + '. Verifique se a planilha foi enviada corretamente.';
  wtpl = 'alerta_rota_vazia'; wparams = [e(v.coordenador || u.nome), e(v.data), e(v.usuario_sem_rota)];
} else if (tipo === 'alerta_checkin_suspeito') {
  text = 'Alerta: check-in de ' + e(v.usuario) + ' na loja ' + e(v.loja) + ' foi registrado a ' + e(v.distancia) + 'm de distância (acima do limite de ' + e(v.raio) + 'm). Verifique.';
  wtpl = 'checkin_suspeito'; wparams = [e(v.usuario), e(v.loja), e(v.distancia), e(v.raio)];
} else {
  text = e(v.texto);
  wtpl = ''; wparams = [];
}
const temBotoes = botoes.length > 0;
let inlineKeyboard = {};
if (temBotoes) {
  inlineKeyboard = { rows: botoes.map(b => ({ row: { buttons: [ { text: e(b.rotulo), additionalFields: { callback_data: e(b.id) } } ] } })) };
}
const wa_params = wparams.map(t => ({ type: 'text', text: t }));
return [{ json: { ok:true, canal: u.canal || 'telegram', chatId: e(u.telegram_chat_id), telefone: e(u.telefone), nome: u.nome, tipo, text, temBotoes, inlineKeyboard, wa_template: wtpl, wa_params } }];
